def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode):
        main = {}
        other = {}
        main_tx = False
        other_tx = False
        main_changes = 0
        other_changes = 0
        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            if conn == "other":
                table = other
                in_tx = other_tx
            else:
                table = main
                in_tx = main_tx
            if op == "begin":
                if conn == "other":
                    other_tx = True
                else:
                    main_tx = True
            elif op == "commit":
                if conn == "other":
                    other_tx = False
                else:
                    main_tx = False
            elif op == "rollback":
                if conn == "other":
                    other_tx = False
                else:
                    main_tx = False
            elif op == "put":
                key = action.get("key")
                value = action.get("value")
                if key in table:
                    if put_mode == "ignore":
                        pass
                    elif put_mode == "replace":
                        table[key] = value
                        if conn == "other":
                            other_changes += 1
                        else:
                            main_changes += 1
                    elif put_mode == "update":
                        table[key] = value
                        if conn == "other":
                            other_changes += 1
                        else:
                            main_changes += 1
                else:
                    table[key] = value
                    if conn == "other":
                        other_changes += 1
                    else:
                        main_changes += 1
            elif op == "update":
                key = action.get("key")
                value = action.get("value")
                if key in table:
                    table[key] = value
                    if conn == "other":
                        other_changes += 1
                    else:
                        main_changes += 1
            elif op == "delete":
                key = action.get("key")
                if key in table:
                    del table[key]
                    if conn == "other":
                        other_changes += 1
                    else:
                        main_changes += 1
        return main, other, main_changes, other_changes

    def committed_state(actions):
        main = {}
        other = {}
        main_tx = False
        other_tx = False
        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            if conn == "other":
                table = other
                in_tx = other_tx
            else:
                table = main
                in_tx = main_tx
            if op == "begin":
                if conn == "other":
                    other_tx = True
                else:
                    main_tx = True
            elif op == "commit":
                if conn == "other":
                    other_tx = False
                else:
                    main_tx = False
            elif op == "rollback":
                if conn == "other":
                    other_tx = False
                else:
                    main_tx = False
            elif op == "put":
                key = action.get("key")
                value = action.get("value")
                if key in table:
                    table[key] = value
                else:
                    table[key] = value
            elif op == "update":
                key = action.get("key")
                value = action.get("value")
                if key in table:
                    table[key] = value
            elif op == "delete":
                key = action.get("key")
                if key in table:
                    del table[key]
        return main, other

    def channel_for(actions, put_mode):
        main, other, mc, oc = simulate(actions, put_mode)
        return mc + oc

    def committed_count(actions):
        main, other = committed_state(actions)
        return len(main) + len(other)

    def committed_sum(actions):
        main, other = committed_state(actions)
        return sum(main.values()) + sum(other.values())

    goal = context.get("goal")
    actions = context.get("actions", [])

    if goal == "committed_count":
        return {"value": committed_count(actions), "unresolved": False}
    if goal == "committed_sum":
        return {"value": committed_sum(actions), "unresolved": False}
    if goal == "channel":
        values = set()
        for mode in ("ignore", "replace", "update"):
            values.add(channel_for(actions, mode))
        if len(values) == 1:
            return {"value": values.pop(), "unresolved": False}
        return {"value": None, "unresolved": True}
    return {"value": None, "unresolved": True}
